```json
[
  {
    "name": "Hotel Aomori",
    "summary": "While the lobby and staff receive praise, Hotel Aomori appears dated with some reviewers citing dusty rooms and thin mattresses.  The buffet dining experience has received negative feedback regarding variety and restocking, and the surrounding area is described as rundown, although the location is convenient."
  },
  {
    "name": "Smile Hotel Aomori",
    "summary": "Smile Hotel Aomori offers clean, budget-friendly accommodations, although rooms can be small. Guests appreciate the impressive all-you-can-eat breakfast and generally find the hotel a good value, but some have noted issues with cigarette smells and limited space for luggage."
  },
  {
    "name": "HOTEL MYSTAYS Aomori Station",
    "summary": "Conveniently located near Aomori Station, HOTEL MYSTAYS Aomori Station provides clean and quiet rooms with rare-for-Japan opening windows. Guests appreciate the courteous staff, easy check-in/out process, and the buffet breakfast and sake tasting offered at the restaurant."
  },
  {
    "name": "Daiwa Roynet Hotel Aomori",
    "summary": "The Daiwa Roynet Hotel Aomori is praised for its luxurious feel, friendly staff, and spacious, clean rooms. Guests particularly enjoy the delicious Japanese buffet breakfast and the convenient location near Aomori Station and local amenities."
  },
  {
    "name": "ART HOTEL Aomori",
    "summary": "While the location of ART HOTEL Aomori is considered nice, some guests have reported issues with cigarette smells in rooms and thin walls. The buffet sashimi is highly rated by some, though discrepancies in online pricing have been noted."
  },
  {
    "name": "Hotel JAL City Aomori",
    "summary": "Hotel JAL City Aomori offers easy access from the train station and a truly impressive breakfast buffet featuring local specialties like sashimi and Aomori apple juice.  However, some guests have noted a smoky smell throughout the hotel and a lack of modern amenities, despite the kind and apologetic staff."
  },
  {
    "name": "APA Hotel Aomori Ekihigashi",
    "summary": "APA Hotel Aomori Ekihigashi is centrally located and within walking distance of Aomori station and major attractions.  While some guests find the rooms small but adequate, others have reported cigarette smells and potential discriminatory behavior from staff."
  },
  {
    "name": "Hoshino Resorts Oirase Keiryu Hotel",
    "summary": "Hoshino Resorts Oirase Keiryu Hotel offers a spacious setting and attentive service, particularly appreciated by families with young children. Guests rave about the delicious meals and the amazing onsen experience, although some have found it difficult to book tours and activities."
  },
  {
    "name": "Toyoko Inn Shin Aomori Eki Higashiguchi",
    "summary": "Toyoko Inn Shin Aomori Eki Higashiguchi is conveniently located near the station and offers clean, modern rooms suitable for solo travelers. While some guests have noted hard beds and plumbing noises, the friendly staff and included breakfast are generally appreciated, though there are few nearby dining options."
  },
  {
    "name": "Hotel Sunroute Aomori",
    "summary": "Hotel Sunroute Aomori offers a reasonable price and good location near tourist attractions. However, guests have noted that the rooms and building are old, with cleanliness issues and thin walls, though the staff is friendly and professional."
  }
]
```
